using System.Globalization;using System.Windows;using AutoPecasERP.Core.Entities;using AutoPecasERP.Data.Context;namespace AutoPecasERP.Desktop.Views;public partial class ProdutoEditWindow:Window{public ProdutoEditWindow(){InitializeComponent();}decimal D(string s){decimal.TryParse(s.Replace(",","."),NumberStyles.Any,CultureInfo.InvariantCulture,out var v);return v;}async void Salvar_Click(object s,RoutedEventArgs e){if(string.IsNullOrWhiteSpace(Codigo.Text)||string.IsNullOrWhiteSpace(Descricao.Text)){MessageBox.Show("Código e descrição são obrigatórios.");return;}using var db=new ErpDbContext();if(db.Produtos.Any(x=>x.CodigoInterno==Codigo.Text.Trim())){MessageBox.Show("Código interno já cadastrado.");return;}db.Produtos.Add(new Produto{CodigoInterno=Codigo.Text.Trim(),CodigoFabricante=Fabricante.Text.Trim(),Descricao=Descricao.Text.Trim(),Marca=Marca.Text.Trim(),Categoria=Categoria.Text.Trim(),Ncm=Ncm.Text.Trim(),Localizacao=Local.Text.Trim(),Custo=D(Custo.Text),PrecoVenda=D(Venda.Text),EstoqueMinimo=D(Minimo.Text),EstoqueMaximo=D(Maximo.Text)});await db.SaveChangesAsync();DialogResult=true;}}